ion":"Dev config: simulates a PSP webhook event for local/sandbox integration testing. Only available when the target provider account environment is development or sandbox. The simulated callback is ingested synchronously through the same status machine as a real PSP webhook (out-trade-no resolution, attempt status update, event record), so the payment takes effect immediately.","operationId":"dev.sandboxTrigger","parameters":[{"$ref":"#/components/parameters/IdempotencyKey"}],"requestBody":{"content":{"application/json":{"schema":{"$ref":"#/components/schemas/SandboxTriggerCommand"}}},"required":true},"responses":{"200":{"content":{"application/json":{"schema":{"$ref":"#/components/schemas/SandboxTriggerResultResponse"}}},"description":"Success"},"400":{"$ref":"#/components/responses/BadRequest"},"401":{"$ref":"#/components/responses/Unauthorized"},"403":{"$ref":"#/components/responses/Forbidden"},"404":{"$ref":"#/components/responses/NotFound"},"409":{"$ref":"#/components/responses/Conflict"},"422":{"$ref":"#/components/responses/UnprocessableEntity"},"429":{"$ref":"#/components/responses/TooManyRequests"},"500":{"$ref":"#/components/responses/InternalError"},"503":{"$ref":"#/components/responses/ServiceUnavailable"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Sandbox event trigger (dev config).","tags":["payments"],"x-sdkwork-api-authority":"sdkwork-payment-backend-api","x-sdkwork-api-surface":"backend-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-domain":"commerce","x-sdkwork-forbid-credential-headers":false,"x-sdkwork-idempotent":true,"x-sdkwork-owner":"sdkwork-payment","x-sdkwork-permission":"commerce.payments.dev.sandbox_trigger","x-sdkwork-request-context":"WebRequestContext","x-sdkwork-resource":"devSandbox","x-sdkwork-server-request-id":true}},"/backend/v3/api/payments/dev/test_payments":{"post":{"description":"Dev config: creates a 0.01 (one-cent) test payment against a QR-capable or web-cashier payment method (wechat_native, alipay_qr — scan-to-pay QR; alipay_wap, alipay_pc — web cashier redirect; stripe_* — client-secret card collection) without requiring an existing order. The method must be active. The backend creates an internal test order and drives the provider checkout, returning the scan-to-pay QR code URL, the web cashier redirect URL/form, or the Stripe client secret. Combine with dev.sandboxTrigger to simulate a success callback in development/sandbox environments.","operationId":"dev.testPayments","parameters":[{"description":"Client retry key for the test payment creation command. The server scopes the key by tenant, principal, and path.","in":"header","name":"Idempotency-Key","required":true,"schema":{"maxLength":128,"minLength":1,"type":"string"}}],"requestBody":{"content":{"application/json":{"schema":{"$ref":"#/components/schemas/CreateTestPaymentCommand"}}},"required":true},"responses":{"200":{"content":{"application/json":{"schema":{"$ref":"#/components/schemas/TestPaymentResponse"}}},"description":"Success"},"400":{"$ref":"#/components/responses/BadRequest"},"401":{"$ref":"#/components/responses/Unauthorized"},"403":{"$ref":"#/components/responses/Forbidden"},"404":{"$ref":"#/components/responses/NotFound"},"409":{"$ref":"#/components/responses/Conflict"},"422":{"$ref":"#/components/responses/UnprocessableEntity"},"429":{"$ref":"#/components/responses/TooManyRequests"},"500":{"$ref":"#/components/responses/InternalError"},"503":{"$ref":"#/components/responses/ServiceUnavailable"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Create a test payment (dev config).","tags":["payments"],"x-sdkwork-api-authority":"sdkwork-payment-backend-api","x-sdkwork-api-surface":"backend-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-domain":"commerce","x-sdkwork-forbid-credential-headers":false,"x-sdkwork-idempotent":true,"x-sdkwork-owner":"sdkwork-payment","x-sdkwork-permission":"commerce.payments.dev.test_payments","x-sdkwork-request-context":"WebRequestContext","x-sdkwork-r