  ('dfb1e0a8-902f-5df7-9811-676b42c267e2', 100001, '966d5996-eaa7-5775-aa0a-be9dfd91a448', 'certificates.retrieve', 'GET', '/backend/v3/api/payments/certificates/{certificateId}', 'Certificate retrieve.', $sdkwork_catalog${"en-US":"Certificate retrieve."}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["payments"]$sdkwork_catalog$::jsonb, FALSE, 360),
