  ('88281d5a-8bd5-5497-80ed-d09ae731f811', 100001, '966d5996-eaa7-5775-aa0a-be9dfd91a448', 'webhookEvents.list', 'GET', '/backend/v3/api/payments/webhook_events', 'Webhook events list.', $sdkwork_catalog${"en-US":"Webhook events list."}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["payments"]$sdkwork_catalog$::jsonb, FALSE, 390),
  ('f3527af7-0042-5f97-86b9-5395f17646b4', 100001, '966d5996-eaa7-5775-aa0a-be9dfd91a448', 'webhookEvents.replay', 'POST', '/backend/v3/api/payments/webhook_events/{eventId}/replay', 'Webhook event replay.', $sdkwork_catalog${"en-US":"Webhook event replay."}$sdkwork_catalog$::jsonb, 'Re-applies stored payment attempt status from the webhook event payload. Replays are capped at WEBHOOK_STORED_REPLAY_MAX_RETRIES (5). Returns 409 when limit exceeded, 404 when event missing.', $sdkwork_catalog${"en-US":"Re-applies stored payment attempt status from the webhook event payload. Replays are capped at WEBHOOK_STORED_REPLAY_MAX_RETRIES (5). Returns 409 when limit exceeded, 404 when event missing."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["payments"]$sdkwork_catalog$::jsonb, FALSE, 400),
  ('237abfef-3b4d-55c0-ba50-82b2f29054d8', 100001, '966d5996-eaa7-5775-aa0a-be9dfd91a448', 'reconciliationRuns.list', 'GET', '/backend/v3/api/payments/reconciliation_runs', 'Reconciliation runs list.', $sdkwork_catalog${"en-US":"Reconciliation runs list."}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["payments"]$sdkwork_catalog$::jsonb, FALSE, 410),
  ('20a1845e-9aa2-56d8-8e1c-a644fd736d68', 100001, '966d5996-eaa7-5775-aa0a-be9dfd91a448', 'reconciliationRuns.create', 'POST', '/backend/v3/api/payments/reconciliation_runs', 'Reconciliation run create.', $sdkwork_catalog${"en-US":"Reconciliation run create."}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["payments"]$sdkwork_catalog$::jsonb, FALSE, 420),
  ('b661c9dd-3db0-5df7-adea-641d353dd023', 100001, '966d5996-eaa7-5775-aa0a-be9dfd91a448', 'dev.sandboxTrigger', 'POST', '/backend/v3/api/payments/dev/sandbox_trigger', 'Sandbox event trigger (dev config).', $sdkwork_catalog${"en-US":"Sandbox event trigger (dev config)."}$sdkwork_catalog$::jsonb, 'Dev config: simulates a PSP webhook event for local/sandbox integration testing. Only available when the target provider account environment is development or sandbox. The simulated callback is ingested synchronously through the same status machine as a real PSP webhook (out-trade-no resolution, attempt status update, event record), so the payment takes effect immediately.', $sdkwork_catalog${"en-US":"Dev config: simulates a PSP webhook event for local/sandbox integration testing. Only available when the target provider account environment is development or sandbox. The simulated callback is ingested synchronously through the same status machine as a real PSP webhook (out-trade-no resolution, attempt status update, event record), so the payment takes effect immediately."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["payments"]$sdkwork_catalog$::jsonb, FALSE, 430),
  ('fbe881df-251d-57b9-9398-7a4aca36804c', 100001, '966d5996-eaa7-5775-aa0a-be9dfd91a448', 'dev.testPayments', 'POST', '/backend/v3/api/payments/dev/test_payments', 'Create a test payment (dev config).', $sdkwork_catalog${"en-US":"Create a test payment (dev config)."}$sdkwork_catalog$::jsonb, 'Dev config: creates a 0.01 (one-cent) test payment against a QR-capable or web-cashier payment method (wechat_native, alipay_qr — scan-to-pay QR; alipay_wap, alipay_pc — web cashier redirect; stripe_* — client-secret card collection) without requiring an existing order. The method must be active. The backend creates an internal test order and drives the provider checkout, returning the scan-to-pay QR code URL, the web cashier redirect URL/form, or the Stripe client secret. Combine with dev.sandboxTrigger to simulate a success callback in development/sandbox environments.', $sdkwork_catalog${"en-US":"Dev config: creates a 0.01 (one-cent) test payment against a QR-capable or web-cashier payment method (wechat_native, alipay_qr — scan-to-pay QR; alipay_wap, alipay_pc — web cashier redirect; stripe_* — client-secret card collection) without requiring an existing order. The method must be active. The backend creates an internal test order and drives the provider checkout, returning the scan-to-pay QR code URL, the web cashier redirect URL/form, or the Stripe client secret. Combine with dev.sandboxTrigger to simulate a success callback in development/sandbox environments."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["payments"]$sdkwork_catalog$::jsonb, FALSE, 440),
  ('94f3387c-6794-5ba6-8936-4512af399842', 100001, '966d5996-eaa7-5775-aa0a-be9dfd91a448', 'dev.checkAttemptStatus', 'POST', '/backend/v3/api/payments/dev/check_attempt_status', 'Check PSP payment status for a dev test payment (dev config).', $sdkwork_catalog${"en-US":"Check PSP payment status for a dev test payment (dev config)."}$sdkwork_catalog$::jsonb, 'Queries the provider for the current payment state of a one-cent test payment attempt and applies the result through the same status machine as the webhook path. Use it after scanning/paying when the provider async notify has not arrived (e.g. Alipay sandbox without a configured callback); the attempt status is updated to succeeded when the provider reports the payment as successful.', $sdkwork_catalog${"en-US":"Queries the provider for the current payment state of a one-cent test payment attempt and applies the result through the same status machine as the webhook path. Use it after scanning/paying when the provider async notify has not arrived (e.g. Alipay sandbox without a configured callback); the attempt status is updated to succeeded when the provider reports the payment as successful."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["payments"]$sdkwork_catalog$::jsonb, FALSE, 450),
  ('47b682d8-8a88-51c8-ba61-937dabcf5ab9', 100001, '966d5996-eaa7-5775-aa0a-be9dfd91a448', 'dev.webhookSignatureTest', 'POST', '/backend/v3/api/payments/dev/webhook_signature_test', 'Webhook signature verification test (dev config).', $sdkwork_catalog${"en-US":"Webhook signature verification test (dev config)."}$sdkwork_catalog$::jsonb, 'Verifies a webhook signature against the database-backed credential for a provider account. Accepts the raw payload, signature header, and timestamp; returns whether verification succeeded and safe diagnostic info.', $sdkwork_catalog${"en-US":"Verifies a webhook signature against the database-backed credential for a provider account. Accepts the raw payload, signature header, and timestamp; returns whether verification succeeded and safe diagnostic info."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["payments"]$sdkwork_catalog$::jsonb, FALSE, 460)
