 previous/new window pair is the point of the record: it is what makes continuous coverage auditable after the version it describes has been superseded.","properties":{"attemptNo":{"type":"integer"},"certificateId":{"format":"uuid","type":"string"},"createdAt":{"format":"date-time","type":"string"},"finishedAt":{"format":"date-time","type":"string"},"id":{"format":"uuid","type":"string"},"lastErrorCode":{"type":"string"},"newNotAfter":{"format":"date-time","type":"string"},"newNotBefore":{"format":"date-time","type":"string"},"previousNotAfter":{"description":"Expiry of the version being replaced, captured when the attempt was claimed, so the handover stays auditable even though that version is now superseded.","format":"date-time","type":"string"},"previousNotBefore":{"format":"date-time","type":"string"},"previousVersionId":{"format":"uuid","type":"string"},"resultingVersionId":{"format":"uuid","type":"string"},"scheduledAt":{"format":"date-time","type":"string"},"startedAt":{"format":"date-time","type":"string"},"status":{"description":"`PLANNED` and `ORDERED` are open, and at most one attempt per certificate may be open; every other value is terminal and carries `finishedAt`.","enum":["PLANNED","ORDERED","SUCCEEDED","FAILED","SKIPPED","CANCELLED"],"type":"string"},"triggerKind":{"description":"`SCHEDULED` came from the due-certificate sweep, `MANUAL` from an operator request. Recorded rather than inferred, because it changes how a failure reads: a scheduled one is broken automation that keeps retrying on its own, a manual one is an act the operator is already watching.","enum":["SCHEDULED","MANUAL"],"type":"string"}},"required":["id","certificateId","triggerKind","status","attemptNo","scheduledAt","createdAt"],"type":"object"},"CertificateResponse":{"properties":{"autoRenew":{"type":"boolean"},"caProfile":{"enum":["LETS_ENCRYPT_STAGING","LETS_ENCRYPT_PRODUCTION","CUSTOM"],"type":"string"},"certName":{"type":"string"},"certificateScope":{"enum":["SINGLE_DOMAIN","WILDCARD"],"type":"string"},"certificateSource":{"enum":["MANAGED","CUSTOM"],"type":"string"},"createdAt":{"format":"date-time","type":"string"},"currentVersionId":{"format":"uuid","type":"string"},"daysUntilExpiry":{"description":"Whole days until the served version expires, floored; negative once past. Floored so that a certificate with twelve hours left and one that expired yesterday cannot both render as `0`.","type":"integer"},"id":{"format":"uuid","type":"string"},"identifiers":{"items":{"format":"hostname","type":"string"},"type":"array"},"issuer":{"type":"string"},"lastRenewalAt":{"description":"When renewal last ran to completion, successfully or not.","format":"date-time","type":"string"},"notAfter":{"format":"date-time","type":"string"},"notBefore":{"format":"date-time","type":"string"},"preferredKeyAlgorithm":{"enum":["RSA","ECDSA"],"type":"string"},"providerAccountId":{"description":"The cloud account pinned to present this certificate's DNS-01 challenges, absent when the certificate defers to its zone or to the deployment-level provider configuration.","type":"string"},"renewBeforeDays":{"description":"Lead time before expiry at which renewal starts. The server sends the derived instants below so every surface agrees on one window rule instead of each re-implementing it.","maximum":90,"minimum":7,"type":"integer"},"renewalDueAt":{"description":"When renewal work becomes due for the version being served: `max(notBefore + lifetime/3, notAfter - renewBeforeDays)`. The lifetime floor keeps a lead time longer than a short-lived certificate's own life from making a fresh certificate immediately due.","format":"date-time","type":"string"},"renewalFailureCount":{"description":"Consecutive failed renewal attempts, reset to zero by a success. Exposed because the retry backoff hides repetition from the schedule: without it a certificate failing every day is indistinguishable from one that has never been tried.","type":"integer"},"renewalStatus":{"enum":["NONE","PLANNED","PROCESSING","FAILED"],"type":"string"},"status":{"enum":["PENDING","ISSUING","ACTIVE","EXPIRED","FAILED","REVOKED"],"type":"string"},"updatedAt":{"format":"date-time","type":"string"},"validationMethod":{"description":"The resolved method the challenge orchestrator must present. A `WILDCARD` certificate always reports `DNS_01`.","enum":["AUTO","HTTP_01","DNS_01"],"type":"string"},"validityPhase":{"description":"Where the served version sits in its validity window right now. Computed at read time, never stored: a persisted phase would be wrong from the instant the clock crossed a boundary.","enum":["NOT_YET_VALID","VALID","EXPIRING_SOON","EXPIRED"],"type":"string"},"version":{"pattern":"^[0-9]+$","type":"string"}},"required":["id","certName","certificateSource","caProfile","certificateScope","validationMethod","preferredKeyAlgorithm","identifiers","autoRenew","renewalStatus","renewBeforeDays","renewalFailureCount","status","createdAt","updatedAt","version"],"type":"object"},"ChannelKey":{"enum":["stable","beta","alpha","qa"],"type":"string"},"ChannelResponse":{"additionalProperties":false,"properties":{"appId":{"format":"uuid","type":"string"},"channelKey":{"$ref":"#/components/schemas/ChannelKey"},"channelStatus":{"type":"string"},"currentReleaseId":{"format":"uuid","type":"string"},"currentReleaseVersion":{"type":"string"},"id":{"format":"uuid","type":"string"},"platformTargetId":{"format":"uuid","type":"string"},"updatedAt":{"format":"date-time","type":"string"},"version":{"type":"string"}},"required":["id","appId","platformTargetId","channelKey","channelStatus","updatedAt","version"],"type":"object"},"ChannelRolloutResponse":{"additionalProperties":false,"properties":{"channelId":{"format":"uuid","type":"string"},"completedAt":{"format":"date-time","type":"string"},"id":{"format":"uuid","type":"string"},"percentage":{"maximum":100,"minimum":1,"type":"integer"},"releaseId":{"format":"uuid","type":"string"},"releaseVersion":{"type":"string"},"requestedAt":