igured and is not.","type":"boolean"},"displayName":{"type":"string"},"dnsProvider":{"description":"The DNS family this account drives, derived from `vendorCode`. Absent for a vendor that drives no supported family, which is why such an account is listed but cannot be bound.","enum":["ALIYUN_DNS","DNSPOD","CLOUDFLARE"],"type":"string"},"environment":{"enum":["development","sandbox","production"],"type":"string"},"id":{"description":"Account id in the provider account center.","type":"string"},"isDefault":{"description":"Whether this account is its level's default for its vendor.","type":"boolean"},"ownerUserId":{"description":"Set for `user`-scope accounts only.","type":"string"},"scopeType":{"enum":["platform","tenant","user"],"type":"string"},"status":{"enum":["active","disabled","archived"],"type":"string"},"tenantGlobal":{"description":"True for `platform` and `tenant` accounts, which any member of the tenant may use; false for an account one user bound to themselves.","type":"boolean"},"vendorCode":{"description":"Cloud vendor, e.g. aliyun, tencent, cloudflare. The account center owns this vocabulary.","type":"string"}},"required":["id","accountCode","displayName","vendorCode","scopeType","tenantGlobal","isDefault","status","credentialConfigured"],"type":"object"},"CompleteDeployUploadSessionRequest":{"properties":{"checksumSha256Hex":{"type":"string"},"contentLength":{"format":"int64","type":"string","x-sdkwork-int64-string":true},"contentType":{"type":"string"},"parts":{"items":{"$ref":"#/components/schemas/CompletedUploadPartInput"},"type":"array"}},"required":["checksumSha256Hex"],"type":"object"},"CompletedUploadPartInput":{"properties":{"etag":{"type":"string"},"partNo":{"format":"int64","type":"string","x-sdkwork-int64-string":true}},"required":["partNo","etag"],"type":"object"},"CompositionKey":{"maxLength":64,"minLength":1,"pattern":"^[A-Za-z0-9._:-]+$","type":"string"},"CreateAppDatabaseMigrationRequest":{"additionalProperties":false,"properties":{"ch