"$ref":"#/components/schemas/ReleaseStatus"},"semanticVersion":{"maxLength":128,"type":"string"}},"required":["platformTargetId","packageId","semanticVersion","idempotencyKey"],"type":"object"},"CreateAppRequest":{"additionalProperties":false,"properties":{"appDomainLabel":{"description":"The `<appId>` prefix of the app's default publishing hostnames (`<appDomainLabel>.app[-<env>].<suffix>`). Must be one lowercase DNS label (alphanumeric plus interior hyphens); absent means the slug is used.","maxLength":63,"type":"string"},"appDomainSuffixes":{"description":"Per-app override of the platform app-domain suffix catalog. Each entry is a lowercase dotted domain without a leading dot; absent means the platform catalog applies.","items":{"maxLength":253,"type":"string"},"maxItems":32,"minItems":1,"type":"array"},"appKind":{"$ref":"#/components/schemas/AppKind"},"defaultEnvironment":{"maxLength":16,"type":"string"},"description":{"maxLength":2000,"type":"string"},"idempotencyKey":{"maxLength":128,"type":"string"},"metadata":{"additionalProperties":true,"description":"Free-form JSONB persisted into deploy_app.metadata (category, media, version, releaseNotes).","type":"object"},"name":{"maxLength":200,"type":"string"},"ownerType":{"$ref":"#/components/schemas/AppOwnerType","description":"Ownership level for the new application. Absent derives it from the request principal — `USER` when a user subject is present, which is the normal case, otherwise `TENANT`. `PLATFORM` is rejected: no permission in this surface distinguishes a platform operator from any other tenant member, so honouring it would let a member publish an app visible to every tenant."},"slug":{"maxLength":120,"type":"string"},"sourceSpecs":{"description":"Optional source specs declared with the app. One app legitimately owns several sources of different specs (a PC build and an H5 build), so declaring them here lets a single create call produce an app whose one publishing hostname already routes by client class. They land in the app's default environment. Exactly one may set `isDefault` when the array is non-empty: it is the fallback for clients no rule classifies.","items":{"$ref":"#/components/schemas/AppSourceSpecDefinition"},"maxItems":32,"type":"array"}},"required":["name","appKind"],"type":"object"},"CreateAppSourceSpecRequest":{"additionalProperties":false,"properties":{"clientArchitecture":{"$ref":"#/components/schemas/AppClientArchitecture"},"clientClassRoutes":{"default":[],"description":"Which client classes this spec serves and at which preference. A class's default is its lowest-ranked spec, and each rank within a class belongs to one spec only, so \"the default spec for MOBILE\" is always defined. Ranks may be sparse while a set is being built up.","items":{"$ref":"#/components/schemas/AppSourceSpecRoute"},"maxItems":12,"type":"array"},"environment":{"$ref":"#/components/schemas/AppPublishEnvironment"},"handler":{"default":"STATIC","enum":["STATIC","SPA","WIKI"],"type":"string"},"indexFiles":{"default":[],"items":{"type":"string"},"maxItems":16,"type":"array"},"isDefault":{"default":false,"type":"boolean"},"label":{"maxLength":64,"minLength":1,"type":"string"},"pathPrefix":{"default":"/","maxLength":4096,"minLength":1,"type":"string"},"priority":{"default":0,"maximum":65535,"minimum":0,"type":"integer"},"runtimeTarget":{"$ref":"#/components/schemas/SdkworkRuntimeTarget"},"spaFallback":{"maxLength":4096,"type":"string"},"specKey":{"$ref":"#/components/schemas/CompositionKey"}},"required":["environment","specKey","label"],"type":"object"},"CreateAppTemplateRequest":{"additionalProperties":false,"properties":{"appUuid":{"format":"uuid","type":"string"},"categoryUuid":{"format":"uuid","type":"string"},"coverMediaRef":{"maxLength":512,"type":"string"},"currency":{"maxLength":8,"type":"string"},"description":{"type":"string"},"displayName":{"maxLength":200,"minLength":1,"type":"string"},"iconMediaRef":{"maxLength":512,"type":"string"},"initialVersion":{"$ref":"#/components/schemas/CreateAppTemplateVersionRequest"},"priceMinor":{"format":"int64","minimum":0,"type":"string","x-sdkwork-int64-string":true,"x-sdkwork-money-unit":"minor"},"pricingModel":{"default":"FREE","enum":["FREE","PAID"],"type":"string"},"summary":{"maxLength":512,"minLength":1,"type":"string"},"templateKey":{"maxLength":64,"minLength":1,"type":"string"},"templateType":{"default":"APP","enum":["APP","PPT","VIDEO"],"type":"string"},"visibility":{"default":"PRIVATE","enum":["PUBLIC","PRIVATE"],"type":"string"}},"required":["appUuid","categoryUuid","templateKey","displayName","summary"],"type":"object"},"CreateAppTemplateVersionRequest":{"additionalProperties":false,"properties":{"artifactUuid":{"format":"uuid","type":"string"},"changelog":{"type":"string"},"checksumSha256":{"maxLength":128,"type":"string"},"packageSizeBytes":{"format":"int64","minimum":0,"type":"string","x-sdkwork-int64-string":true},"platformTargets":{"items":{"type":"string"},"type":"array"},"sourceAppVersion":{"maxLength":64,"type":"string"},"version":{"maxLength":64,"minLength":1,"type":"string"}},"required":["version"],"type":"object"},"CreateArtifactRequest":{"additionalProperties":false,"properties":{"checksumSha256":{"pattern":"^[A-Fa-f0-9]{64}$","type":"string"},"contentLength":{"format":"int64","minimum":1,"type":"string","x-sdkwork-int64-string":true},"contentType":{"maxLength":255,"minLength":1,"type":"string"},"driveNodeId":{"minLength":1,"type":"string"},"driveSpaceId":{"minLength":1,"type":"string"},"driveUploadItemId":{"minLength":1,"type":"string"},"driveUploadSessionId":{"minLength":1,"type":"string"},"fileName":{"maxLength":255,"minLength":1,"type":"string"},"idempotencyKey":{"maxLength":128,"minLength":8,"type":"string"},"packageType":{"maximum":5,"minimum":1,"type":"integer"},"siteId":{"format":"uuid","type":"string"}},"required":["packageType","fileName","contentType","contentLength","driveUploadSessionId","driveSpaceId","driveNodeId","idempotencyKey"],"type":"object"},"CreateBuildRequest":{"additionalProperties":false,"properties":{"idempotencyKey":{"maxLength":128,"type":"string"},"platformTargetId":{"format":"uuid","type":"string"},"semanticVersion":{"maxLength":128,"type":"string"},"sourceRef":{"maxLength":255,"type":"string"},"sourceRepositoryId":{"format":"uuid","type":"string"},"templateId":{"format":"uuid","type":"string"}},"required":["platformTargetId","idempotencyKey"],"type":"object"},"CreateBuildTemplateRequest":{"additionalProperties":false,"properties":{"artifactOutputs":{"items":{"maxLength":500,"type":"string"},"maxItems":64,"type":"array"},"commands":{"items":{"maxLength":500,"type":"string"},"maxItems":64,"type":"array"},"idempotencyKey":{"maxLength":128,"type":"string"},"platform":{"$ref":"#/components/schemas/Platform"},"qualityGates":{"type":"object"},"techStack":{"$ref":"#/components/schemas/TechStack"},"templateName":{"maxLength":200,"type":"string"},"templateVersion":{"maxLength":64,"type":"string"},"toolchain":{"type":"object"}},"required":["templateName","templateVersion","platform"],"type":"object"},"CreateCertificateRequest":{"properties":{"autoRenew":{"default":true,"description":"Whether the control plane keeps this certificate renewed on its own. Defaults to true: asking for a managed certificate means asking for a name that stays covered, not for a reminder to renew it.","type":"boolean"},"caProfile":{"default":"LETS_ENCRYPT_PRODUCTION","enum":["LETS_ENCRYPT_STAGING","LETS_ENCRYPT_PRODUCTION"],"type":"string"},"certName":{"maxLength":200,"minLength":1,"type":"string"},"certificateScope":{"default":"SINGLE_DOMAIN","description":"`SINGLE_DOMAIN` issues for the exact names supplied. `WILDCARD` additionally plans the apex of each wildcard, because a wildcard SAN does not cover its own apex, and forces DNS-01 validation.","enum":["SINGLE_DOMAIN","WILDCARD"],"type":"string"},"domainIds":{"items":{"format":"uuid","type":"string"},"maxItems":100,"minItems":1,"type":"array","uniqueItems":true},"preferredKeyAlgorithm":{"default":"RSA","description":"Key algorithm of the issued leaf. Defaults to RSA: a managed certificate is renewed unattended and RSA-2048 is the leaf key every TLS client accepts, so a certificate requested without an opinion on this stays reachable from old stacks as well. Ask for ECDSA explicitly where every client is known to support P-256.","enum":["RSA","ECDSA"],"type":"string"},"providerAccountId":{"description":"Cloud account that presents this certificate's DNS-01 challenges, overriding the zone's pin so one zone can issue through several vendor accounts. Optional: omitting it leaves the certificate deferring to its zone, then to the account center, then to the deployment-level provider configuration, decided when an order runs.","maxLength":128,"minLength":1,"pattern":"^[A-Za-z0-9][A-Za-z0-9_.:-]{1,127}$","type":"string"},"renewBeforeDays":{"default":30,"description":"Days before expiry at which renewal starts. Stored per certificate rather than read from the app binding's TLS policy, because one certificate may back several listeners with different policies and a renewal trigger has to resolve to exactly one window. The configured lead time is additionally floored at one third of the certificate's lifetime, so a value larger than a short-lived certificate's lifetime cannot make a fresh certificate immediately due.","maximum":90,"minimum":7,"type":"integer"},"validationMethod":{"default":"AUTO","description":"Operator preference. `AUTO` resolves to HTTP_01 for a `SINGLE_DOMAIN` scope and always to DNS_01 for `WILDCARD`. `HTTP_01` is rejected for a `WILDCARD` scope.","enum":["AUTO","HTTP_01","DNS_01"],"type":"string"}},"required":["certName","domainIds"],"type":"object"},"CreateCloudAccountRequest":{"additionalProperties":false,"description":"The credential halves the chosen family needs, so the console renders the vendor's own field names for that family rather than a union of every family's: `accessKeyId` is the public half (Aliyun AccessKeyId, DNSPod LoginId) and is absent for Cloudflare, while `secretAccessKey` is always the secret half (Aliyun AccessKeySecret, DNSPod ApiToken, Cloudflare ApiToken). A `dns_provider` that names no supported family is refused rather than stored, because a credential whose vendor does not match the domain it will publish for fails at the first order.","properties":{"accessKeyId":{"description":"Required by the key-pair families, ignored by bearer-token ones.","maxLength":256,"type":"string"},"accountCode":{"description":"The account code within its scope, pre-filled by the console with a suggestion rather than derived server-side: a derived code collides the second time a tenant adds a second account for the same vendor.","maxLength":32,"minLength":2,"pattern":"^[a-z][a-z0-9_]*$","type":"string"},"confirmsCredential":{"default":false,"description":"The operator's own statement that the credential is an active one for the declared vendor with permission to edit the zones it will publish into. The console cannot probe a credential — that would mean dispatching it to the vendor from the read path — so it asks the operator instead, and this is what records that they were asked. Refused when false rather than silently defaulted, so a caller cannot store an unattested credential by omission.","type":"boolean"},"displayName":{"maxLength":200,"minLength":1,"type":"string"},"dnsProvider":{"enum":["ALIYUN_DNS","DNSPOD","CLOUDFLARE"],"type":"string"},"environment":{"enum":["development","sandbox","production"],"type":"string"},"isDefault":{"default":false,"description":"Promote this account to its level's default for its vendor.","type":"boolean"},"scopeType":{"default":"tenant","description":"A tenant member may not publish a `platform` account; the account center refuses it, and the console offers the level only where it can succeed.","enum":["platform","tenant","user"],"type":"string"},"secretAccessKey":{"maxLength":1024,"minLength":1,"type":"string","writeOnly":true},"sessionToken"