on. The literal cannot collide with a real account id, because the id shape admits only ASCII alphanumerics and `_.:-` after a leading alphanumeric. A facet, not a grant: it can only narrow the zones the owner gate already allows the caller to reach.","in":"query","name":"provider_account_id","schema":{"maxLength":128,"type":"string"}}],"responses":{"200":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"additionalProperties":false,"properties":{"items":{"items":{"$ref":"#/components/schemas/DomainZoneResponse"},"type":"array"},"pageInfo":{"$ref":"#/components/schemas/PageInfo"}},"required":["items","pageInfo"],"type":"object"}},"required":["data"],"type":"object"}]}}},"description":"Success"},"401":{"content":{"application/problem+json":{"schema":{"$ref":"#/components/schemas/ProblemDetail"}}},"description":"未认证"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"List root domain zones","tags":["domain"],"x-sdkwork-api-authority":"sdkwork-deploy-app-api","x-sdkwork-api-surface":"app-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-owner":"sdkwork-deploy","x-sdkwork-permission":"deploy.domainZones.read","x-sdkwork-request-context":"WebRequestContext"},"post":{"operationId":"domainZones.create","parameters":[{"$ref":"#/components/parameters/IdempotencyKeyParam"}],"requestBody":{"content":{"application/json":{"schema":{"$ref":"#/components/schemas/CreateDomainZoneRequest"}}},"required":true},"responses":{"201":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"item":{"$ref":"#/components/schemas/DomainZoneResponse"}},"required":["item"],"type":"object"}},"required":["data"],"type":"object"}]}}},"description":"Created"},"409":{"content":{"application/problem+json":{"schema":{"$ref":"#/components/schemas/ProblemDetail"}}},"description":"资源冲突"},"422":{"content":{"application/problem+json":{"schema":{"$ref":"#/components/schemas/ProblemDetail"}}},"description":"校验错误"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Define a root domain zone","tags":["domain"],"x-sdkwork-api-authority":"sdkwork-deploy-app-api","x-sdkwork-api-surface":"app-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-idempotent":true,"x-sdkwork-owner":"sdkwork-deploy","x-sdkwork-permission":"deploy.domainZones.write","x-sdkwork-request-context":"WebRequestContext"}},"/app/v3/api/domain_zones/{zoneId}":{"delete":{"operationId":"domainZones.delete","parameters":[],"responses":{"204":{"description":"Deleted"},"404":{"content":{"application/problem+json":{"schema":{"$ref":"#/components/schemas/ProblemDetail"}}},"description":"资源不存在"},"409":{"content":{"application/problem+json":{"schema":{"$ref":"#/components/schemas/ProblemDetail"}}},"description":"资源冲突"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Delete an empty root domain zone","tags":["domain"],"x-sdkwork-api-authority":"sdkwork-deploy-app-api","x-sdkwork-api-surface":"app-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-owner":"sdkwork-deploy","x-sdkwork-permission":"deploy.domainZones.write","x-sdkwork-request-context":"WebRequestContext"},"get":{"operationId":"domainZones.retrieve","parameters":[],"responses":{"200":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"item":{"$ref":"#/components/schemas/DomainZoneResponse"}},"required":["item"],"type":"object"}},"required":["data"],"type":"object"}]}}},"description":"Success"},"404":{"content":{"application/problem+json":{"schema":{"$ref":"#/components/schemas/ProblemDetail"}}},"description":"资源不存在"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Retrieve a root domain zone","tags":["domain"],"x-sdkwork-api-authority":"sdkwork-deploy-app-api","x-sdkwork-api-surface":"app-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-owner":"sdkwork-deploy","x-sdkwork-permission":"deploy.domainZones.read","x-sdkwork-request-context":"WebRequestContext"},"parameters":[{"$ref":"#/components/parameters/DomainZoneIdParam"}],"patch":{"operationId":"domainZones.update","parameters":[],"requestBody":{"content":{"application/json":{"schema":{"$ref":"#/components/schemas/UpdateDomainZoneRequest"}}},"required":true},"responses":{"200":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"item":{"$ref":"#/components/schemas/DomainZoneResponse"}},"required":["item"],"type":"object"}},"required":["data"],"type":"object"}]}}},"description":"Updated"},"404":{"content":{"application/problem+json":{"schema":{"$ref":"#/components/schemas/ProblemDetail"}}},"description":"资源不存在"},"422":{"content":{"application/problem+json":{"schema":{"$ref":"#/components/schemas/ProblemDetail"}}},"description":"校验错误"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Update a root domain zone","tags":["domain"],"x-sdkwork-api-authority":"sdkwork-deploy-app-api","x-sdkwork-api-surface":"app-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-owner":"sdkwork-deploy","x-sdkwork-permission":"deploy.domainZones.write","x-sdkwork-request-context":"WebRequestContext"}},"/app/v3/api/domain_zones/{zoneId}/dns_records":{"get":{"description":"Pages the resolution-record snapshot the last cloud-account sync read from the provider: record type and record content (the resolution IP for A/AAAA, the target for CNAME/MX) per owner. The read never contacts the provider — `domainZones.dnsRecords.sync` does that. A record whose owner matches no registered hostname still shows here at Zone scope; a record matched to a hostname deleted after the sync does not.","operationId":"domainZones.dnsRecords.list","parameters":[{"$ref":"#/components/parameters/PageParam"},{"$ref":"#/components/parameters/PageSizeParam"},{"description":"Restrict the page to one registered hostname by id. The sync has already applied the wildcard semantics when it stamped each record with its hostname — a wildcard declaration's rows are its star record, its base owner and every owner exactly one label beneath it — so the filter is one equality, not a name match.","in":"query","name":"hostname_id","schema":{"format":"uuid","type":"string"}},{"description":"Restrict the page to records whose 主机记录 (zone-relative owner) contains this keyword, case-insensitive.","in":"query","name":"host","schema":{"maxLength":253,"minLength":1,"type":"string"}},{"description":"Restrict the page to one record type (exact spelling, e.g. `A`).","in":"query","name":"record_type","schema":{"enum":["A","AAAA","CNAME","TXT","MX","NS","CAA"],"type":"string"}}],"responses":{"200":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"additionalProperties":false,"properties":{"items":{"items":{"$ref":"#/components/schemas/DomainDnsRecordResponse"},"type":"array"},"pageInfo":{"$ref":"#/components/schemas/PageInfo"}},"required":["items","pageInfo"],"type":"object"}},"required":["data"],"type":"object"}]}}},"description":"Zone resolution records returned successfully."},"404":{"content":{"application/problem+json":{"schema":{"$ref":"#/components/schemas/ProblemDetail"}}},"description":"资源不存在"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"List a Zone's synced DNS resolution records","tags":["domain"],"x-sdkwork-api-authority":"sdkwork-deploy-app-api","x-sdkwork-api-surface":"app-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-owner":"sdkwork-deploy","x-sdkwork-permission":"deploy.domainZones.read","x-sdkwork-request-context":"WebRequestContext"},"parameters":[{"$ref":"#/components/parameters/DomainZoneIdParam"}],"post":{"description":"Validates the change (type in the managed set, owner in the DNS label alphabet, value parsed per type) and writes it through the Zone's cloud account, then joins the vendor's answer to the stored snapshot. The owner is the zone-relative 主机记录 (`@`, `www`, `*`); an owner already carrying the zone suffix is refused before the vendor is asked.","operationId":"domainZones.dnsRecords.create","parameters":[{"$ref":"#/components/parameters/IdempotencyKeyParam"}],"requestBody":{"content":{"application/json":{"schema":{"$ref":"#/components/schemas/CreateDomainDnsRecordRequest"}}},"required":true},"responses":{"201":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"item":{"$ref":"#/components/schemas/DomainDnsRecordResponse"}},"required":["item"],"type":"object"}},"required":["data"],"type":"object"}]}}},"description":"Resolution record created successfully."},"404":{"content":{"application/problem+json":{"schema":{"$ref":"#/components/schemas/ProblemDetail"}}},"description":"资源不存在"},"422":{"content":{"application/problem+json":{"schema":{"$ref":"#/components/schemas/ProblemDetail"}}},"description":"校验错误"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Create a resolution record through the Zone's cloud account","tags":["domain"],"x-sdkwork-api-authority":"sdkwork-deploy-app-api","x-sdkwork-api-surface":"app-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-idempotent":true,"x-sdkwork-owner":"sdkwork-deploy","x-sdkwork-permission":"deploy.domainZones.write","x-sdkwork-request-context":"WebRequestContext"}},"/app/v3/api/domain_zones/{zoneId}/dns_records/sync":{"parameters":[{"$ref":"#/components/parameters/DomainZoneIdParam"}],"post":{"description":"Re-reads the Zone's record inventory from its DNS provider through the same presenter chain certificate issuance uses — the Zone's pinned account, then the account center's choice for the declared provider, then the deployment-level configuration — and replaces the stored snapshot whole. Two syncs in a row answer with equivalent snapshots, so the operation is idempotent.","operationId":"domainZones.dnsRecords.sync","parameters":[{"