  ('2e266657-89b2-5a4e-8152-4f474f9416c2', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'domainZones.list', 'GET', '/app/v3/api/domain_zones', 'List root domain zones', $sdkwork_catalog${"en-US":"List root domain zones"}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["domain"]$sdkwork_catalog$::jsonb, FALSE, 10),
