  ('6901ceae-9484-57c9-b96a-8c53af27071d', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'domainZones.retrieve', 'GET', '/app/v3/api/domain_zones/{zoneId}', 'Retrieve a root domain zone', $sdkwork_catalog${"en-US":"Retrieve a root domain zone"}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["domain"]$sdkwork_catalog$::jsonb, FALSE, 30),
