  ('638595a2-1b6a-51c5-91af-326f76e98135', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'domainZones.wechatVerification.retrieve', 'GET', '/app/v3/api/domain_zones/{zoneId}/wechat_verification', 'Read the Zone''s WeChat MP domain-ownership verification file', $sdkwork_catalog${"en-US":"Read the Zone's WeChat MP domain-ownership verification file"}$sdkwork_catalog$::jsonb, 'The platform-issued MP_verify_xxx.txt file this Zone publishes, if any.
The edge serves it verbatim at https://<hostname>/<fileName> for every
hostname in the Zone; a subdomain and the apex manage the same file.', $sdkwork_catalog${"en-US":"The platform-issued MP_verify_xxx.txt file this Zone publishes, if any.\nThe edge serves it verbatim at https://<hostname>/<fileName> for every\nhostname in the Zone; a subdomain and the apex manage the same file."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["domain"]$sdkwork_catalog$::jsonb, FALSE, 60),
  ('d90a15d3-995f-5e49-960a-f8b10168aaa5', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'domainZones.wechatVerification.upsert', 'PUT', '/app/v3/api/domain_zones/{zoneId}/wechat_verification', 'Upload (or wholly replace) the Zone''s WeChat verification file', $sdkwork_catalog${"en-US":"Upload (or wholly replace) the Zone's WeChat verification file"}$sdkwork_catalog$::jsonb, 'Content is stored byte-exact: WeChat compares bytes, so nothing is
normalized. A fresh platform file replaces the previous one whole.', $sdkwork_catalog${"en-US":"Content is stored byte-exact: WeChat compares bytes, so nothing is\nnormalized. A fresh platform file replaces the previous one whole."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["domain"]$sdkwork_catalog$::jsonb, FALSE, 70),
  ('f5d8d333-a917-53e2-97c6-b16d621a82d9', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'domainZones.wechatVerification.delete', 'DELETE', '/app/v3/api/domain_zones/{zoneId}/wechat_verification', 'Delete the Zone''s WeChat verification file', $sdkwork_catalog${"en-US":"Delete the Zone's WeChat verification file"}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["domain"]$sdkwork_catalog$::jsonb, FALSE, 80),
  ('fc609d82-bdcd-557f-9206-3d5863a13f3c', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'domainZones.wechatVerification.check', 'POST', '/app/v3/api/domain_zones/{zoneId}/wechat_verification/check', 'Self-check the Zone''s WeChat verification file', $sdkwork_catalog${"en-US":"Self-check the Zone's WeChat verification file"}$sdkwork_catalog$::jsonb, 'Fetches https://<apex>/<fileName> the way the WeChat crawler does
(falling back to http to separate "no TLS" from "no DNS") and compares
the body byte-for-byte with the stored file. Never throws: transport
failures fold into the returned facts.', $sdkwork_catalog${"en-US":"Fetches https://<apex>/<fileName> the way the WeChat crawler does\n(falling back to http to separate \"no TLS\" from \"no DNS\") and compares\nthe body byte-for-byte with the stored file. Never throws: transport\nfailures fold into the returned facts."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["domain"]$sdkwork_catalog$::jsonb, FALSE, 90),
  ('aed51c8f-ab49-55ad-8a25-5f60b4801bb4', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'domainZones.hostnames.list', 'GET', '/app/v3/api/domain_zones/{zoneId}/hostnames', 'List hostnames in a root domain zone', $sdkwork_catalog${"en-US":"List hostnames in a root domain zone"}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["domain"]$sdkwork_catalog$::jsonb, FALSE, 100),
  ('c6d7cdb6-1695-5037-aec2-7add467222f3', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'domainZones.hostnames.create', 'POST', '/app/v3/api/domain_zones/{zoneId}/hostnames', 'Create a hostname in a root domain zone', $sdkwork_catalog${"en-US":"Create a hostname in a root domain zone"}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["domain"]$sdkwork_catalog$::jsonb, FALSE, 110),
  ('1f3c7eb9-dcc0-52c9-8f5e-57d0cda4e2ea', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'domainZones.hostnames.retrieve', 'GET', '/app/v3/api/domain_zones/{zoneId}/hostnames/{hostnameId}', 'Retrieve a domain hostname', $sdkwork_catalog${"en-US":"Retrieve a domain hostname"}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["domain"]$sdkwork_catalog$::jsonb, FALSE, 120),
  ('3122a44a-f042-5761-997f-fef97f44696c', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'domainZones.hostnames.update', 'PATCH', '/app/v3/api/domain_zones/{zoneId}/hostnames/{hostnameId}', 'Rename a domain hostname', $sdkwork_catalog${"en-US":"Rename a domain hostname"}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["domain"]$sdkwork_catalog$::jsonb, FALSE, 130),
  ('93c18753-ec76-576d-9646-72f57e4a33c0', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'domainZones.hostnames.delete', 'DELETE', '/app/v3/api/domain_zones/{zoneId}/hostnames/{hostnameId}', 'Delete an unbound domain hostname', $sdkwork_catalog${"en-US":"Delete an unbound domain hostname"}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["domain"]$sdkwork_catalog$::jsonb, FALSE, 140),
  ('c2b95a75-0ac7-5fcc-8c9c-3ae4a44a2743', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'domainZones.hostnames.verify', 'POST', '/app/v3/api/domain_zones/{zoneId}/hostnames/{hostnameId}/verify', 'Verify domain hostname ownership', $sdkwork_catalog${"en-US":"Verify domain hostname ownership"}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["domain"]$sdkwork_catalog$::jsonb, FALSE, 150),
  ('7aa2bb19-04f9-5f76-98c1-f0ae85254cac', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'domainZones.hostnameClaims.ensure', 'POST', '/app/v3/api/domain_zones/{zoneId}/hostname_claims', 'Ensure ownership of a set of hostnames', $sdkwork_catalog${"en-US":"Ensure ownership of a set of hostnames"}$sdkwork_catalog$::jsonb, 'Declares whichever of the requested hostnames the tenant does not own yet and runs one ownership check over each of them, so an order covering N names costs one round trip instead of 2N. The hostnames are fully qualified names rather than zone-relative ones: the server folds them back, because every caller that re-derives the fold is a place for the leading "*." to be applied twice.', $sdkwork_catalog${"en-US":"Declares whichever of the requested hostnames the tenant does not own yet and runs one ownership check over each of them, so an order covering N names costs one round trip instead of 2N. The hostnames are fully qualified names rather than zone-relative ones: the server folds them back, because every caller that re-derives the fold is a place for the leading \"*.\" to be applied twice."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["domain"]$sdkwork_catalog$::jsonb, FALSE, 160),
  ('09739b3f-04c3-5b2a-bad6-455064e63902', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'domainZones.dnsRecords.list', 'GET', '/app/v3/api/domain_zones/{zoneId}/dns_records', 'List a Zone''s synced DNS resolution records', $sdkwork_catalog${"en-US":"List a Zone's synced DNS resolution records"}$sdkwork_catalog$::jsonb, 'Pages the resolution-record snapshot the last cloud-account sync read from the provider: record type and record content (the resolution IP for A/AAAA, the target for CNAME/MX) per owner. The read never contacts the provider — `domainZones.dnsRecords.sync` does that. A record whose owner matches no registered hostname still shows here at Zone scope; a record matched to a hostname deleted after the sync does not.', $sdkwork_catalog${"en-US":"Pages the resolution-record snapshot the last cloud-account sync read from the provider: record type and record content (the resolution IP for A/AAAA, the target for CNAME/MX) per owner. The read never contacts the provider — `domainZones.dnsRecords.sync` does that. A record whose owner matches no registered hostname still shows here at Zone scope; a record matched to a hostname deleted after the sync does not."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["domain"]$sdkwork_catalog$::jsonb, FALSE, 170),
  ('8addfd4c-2a95-5791-8972-370977539a79', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'domainZones.dnsRecords.create', 'POST', '/app/v3/api/domain_zones/{zoneId}/dns_records', 'Create a resolution record through the Zone''s cloud account', $sdkwork_catalog${"en-US":"Create a resolution record through the Zone's cloud account"}$sdkwork_catalog$::jsonb, 'Validates the change (type in the managed set, owner in the DNS label alphabet, value parsed per type) and writes it through the Zone''s cloud account, then joins the vendor''s answer to the stored snapshot. The owner is the zone-relative 主机记录 (`@`, `www`, `*`); an owner already carrying the zone suffix is refused before the vendor is asked.', $sdkwork_catalog${"en-US":"Validates the change (type in the managed set, owner in the DNS label alphabet, value parsed per type) and writes it through the Zone's cloud account, then joins the vendor's answer to the stored snapshot. The owner is the zone-relative 主机记录 (`@`, `www`, `*`); an owner already carrying the zone suffix is refused before the vendor is asked."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["domain"]$sdkwork_catalog$::jsonb, FALSE, 180),
  ('682b0876-b546-5ade-ac0f-6a24d6f8748c', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'domainZones.dnsRecords.sync', 'POST', '/app/v3/api/domain_zones/{zoneId}/dns_records/sync', 'Sync a Zone''s resolution records through its cloud account', $sdkwork_catalog${"en-US":"Sync a Zone's resolution records through its cloud account"}$sdkwork_catalog$::jsonb, 'Re-reads the Zone''s record inventory from its DNS provider through the same presenter chain certificate issuance uses — the Zone''s pinned account, then the account center''s choice for the declared provider, then the deployment-level configuration — and replaces the stored snapshot whole. Two syncs in a row answer with equivalent snapshots, so the operation is idempotent.', $sdkwork_catalog${"en-US":"Re-reads the Zone's record inventory from its DNS provider through the same presenter chain certificate issuance uses — the Zone's pinned account, then the account center's choice for the declared provider, then the deployment-level configuration — and replaces the stored snapshot whole. Two syncs in a row answer with equivalent snapshots, so the operation is idempotent."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["domain"]$sdkwork_catalog$::jsonb, FALSE, 190),
  ('c53cac96-079f-5be2-852a-d431e26670d8', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'domainZones.dnsRecords.update', 'PATCH', '/app/v3/api/domain_zones/{zoneId}/dns_records/{recordId}', 'Replace a resolution record in place through the Zone''s cloud account', $sdkwork_catalog${"en-US":"Replace a resolution record in place through the Zone's cloud account"}$sdkwork_catalog$::jsonb, 'A full replace of owner/type/value/TTL — the update shape every integrated vendor shares — followed by the same replace in the stored snapshot. The provider-side pause state is not touched here; only the status operation flips it.', $sdkwork_catalog${"en-US":"A full replace of owner/type/value/TTL — the update shape every integrated vendor shares — followed by the same replace in the stored snapshot. The provider-side pause state is not touched here; only the status operation flips it."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["domain"]$sdkwork_catalog$::jsonb, FALSE, 200),
  ('e14d4ca4-2688-5ba5-9bc4-c31fa820545e', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'domainZones.dnsRecords.delete', 'DELETE', '/app/v3/api/domain_zones/{zoneId}/dns_records/{recordId}', 'Delete a resolution record through the Zone''s cloud account', $sdkwork_catalog${"en-US":"Delete a resolution record through the Zone's cloud account"}$sdkwork_catalog$::jsonb, 'Deletes on the provider first and removes the stored row second, so a failed vendor delete never leaves a page serving a name the zone does not answer.', $sdkwork_catalog${"en-US":"Deletes on the provider first and removes the stored row second, so a failed vendor delete never leaves a page serving a name the zone does not answer."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["domain"]$sdkwork_catalog$::jsonb, FALSE, 210),
  ('430d1c57-9ed0-5c55-ac5b-67f54cdb5955', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'domainZones.dnsRecords.status.update', 'PATCH', '/app/v3/api/domain_zones/{zoneId}/dns_records/{recordId}/status', 'Pause a resolution record or resume it', $sdkwork_catalog${"en-US":"Pause a resolution record or resume it"}$sdkwork_catalog$::jsonb, 'The provider is flipped first and the stored row second, so a failed vendor call never leaves the page claiming a state the vendor did not accept. A vendor without a per-record pause (Cloudflare) answers its own refusal.', $sdkwork_catalog${"en-US":"The provider is flipped first and the stored row second, so a failed vendor call never leaves the page claiming a state the vendor did not accept. A vendor without a per-record pause (Cloudflare) answers its own refusal."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["domain"]$sdkwork_catalog$::jsonb, FALSE, 220),
  ('5b2e3974-3778-5537-9120-756adb0a0310', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'cloudAccounts.list', 'GET', '/app/v3/api/cloud_accounts', 'List cloud accounts usable for DNS automation', $sdkwork_catalog${"en-US":"List cloud accounts usable for DNS automation"}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["domain"]$sdkwork_catalog$::jsonb, FALSE, 230),
