  ('2f0a976a-02bc-529c-972f-ee9d3561f197', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'certificates.retrieve', 'GET', '/app/v3/api/certificates/{certificateId}', '获取证书详情', $sdkwork_catalog${"en-US":"获取证书详情"}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["certificate"]$sdkwork_catalog$::jsonb, FALSE, 270),
  ('8c2c446b-520c-55ba-a37b-79132ace8b38', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'certificates.delete', 'DELETE', '/app/v3/api/certificates/{certificateId}', '撤销证书', $sdkwork_catalog${"en-US":"撤销证书"}$sdkwork_catalog$::jsonb, '撤销证书生命周期聚合并停止自动续期；密钥材料由 Secret Manager/KMS 生命周期独立管理。', $sdkwork_catalog${"en-US":"撤销证书生命周期聚合并停止自动续期；密钥材料由 Secret Manager/KMS 生命周期独立管理。"}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["certificate"]$sdkwork_catalog$::jsonb, FALSE, 280),
  ('a2f6b5d6-aa5b-506a-95ea-0a7b8410d032', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'certificates.renew', 'POST', '/app/v3/api/certificates/{certificateId}/renew', '计划托管证书续期', $sdkwork_catalog${"en-US":"计划托管证书续期"}$sdkwork_catalog$::jsonb, '仅适用于已激活且启用自动续期的托管证书；命令将续期状态原子调整为 PLANNED，由 ACME worker 领取。', $sdkwork_catalog${"en-US":"仅适用于已激活且启用自动续期的托管证书；命令将续期状态原子调整为 PLANNED，由 ACME worker 领取。"}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["certificate"]$sdkwork_catalog$::jsonb, FALSE, 290),
  ('5bb4b5da-8e00-5901-b421-2296fa781645', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'certificates.renewals.list', 'GET', '/app/v3/api/certificates/{certificateId}/renewals', '获取证书续期历史', $sdkwork_catalog${"en-US":"获取证书续期历史"}$sdkwork_catalog$::jsonb, '返回该证书的续期尝试台账，按创建时间倒序。每条记录保留本次尝试交接的 有效期窗口（previousNotBefore/previousNotAfter 与 newNotBefore/newNotAfter）， 因此证书被替换之后，「这个域名在某个时间段由哪张证书覆盖」仍然可以回答； 证书自身只保存当前状态，历史版本一旦被取代就无法从这里复原。', $sdkwork_catalog${"en-US":"返回该证书的续期尝试台账，按创建时间倒序。每条记录保留本次尝试交接的 有效期窗口（previousNotBefore/previousNotAfter 与 newNotBefore/newNotAfter）， 因此证书被替换之后，「这个域名在某个时间段由哪张证书覆盖」仍然可以回答； 证书自身只保存当前状态，历史版本一旦被取代就无法从这里复原。"}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["certificate"]$sdkwork_catalog$::jsonb, FALSE, 300),
