  ('1e6beeaa-c17d-5484-9765-fd8e7bb037cd', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'uploadSessions.cancel', 'POST', '/app/v3/api/upload_sessions/{uploadSessionId}/cancel', '取消上传会话', $sdkwork_catalog${"en-US":"取消上传会话"}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["uploadSession"]$sdkwork_catalog$::jsonb, FALSE, 340),
