  ('982abb45-63ba-561d-8d42-76de0d2156b2', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'artifacts.delete', 'DELETE', '/app/v3/api/artifacts/{artifactId}', '保留并下架制品', $sdkwork_catalog${"en-US":"保留并下架制品"}$sdkwork_catalog$::jsonb, '将制品标记为 retained；Drive 节点生命周期仍由 Drive 管理。', $sdkwork_catalog${"en-US":"将制品标记为 retained；Drive 节点生命周期仍由 Drive 管理。"}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["artifact"]$sdkwork_catalog$::jsonb, FALSE, 380),
  ('e92ddbc3-98d2-56bd-a6f5-025e59181a0c', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'apps.list', 'GET', '/app/v3/api/apps', 'List the apps the caller may reach', $sdkwork_catalog${"en-US":"List the apps the caller may reach"}$sdkwork_catalog$::jsonb, 'Returns the applications this subject can reach, which is the two tenant-wide ownership levels (`PLATFORM`, `TENANT`) plus their own personal apps and their organization''s apps. Reach is decided server-side from the request principal; `scope` can only narrow the page, never widen it.', $sdkwork_catalog${"en-US":"Returns the applications this subject can reach, which is the two tenant-wide ownership levels (`PLATFORM`, `TENANT`) plus their own personal apps and their organization's apps. Reach is decided server-side from the request principal; `scope` can only narrow the page, never widen it."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["app"]$sdkwork_catalog$::jsonb, FALSE, 390),
