  ('1cede8ff-f466-5fa0-99d6-9351ee611034', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'apps.update', 'PATCH', '/app/v3/api/apps/{appId}', 'Update a tenant app', $sdkwork_catalog${"en-US":"Update a tenant app"}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["app"]$sdkwork_catalog$::jsonb, FALSE, 420),
