  ('1fdad6e7-cb44-5d24-a774-79f5db8de34c', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'apps.domains.list', 'GET', '/app/v3/api/apps/{appId}/domains', 'List an app''s publishing domains', $sdkwork_catalog${"en-US":"List an app's publishing domains"}$sdkwork_catalog$::jsonb, 'Returns every hostname the app publishes on — the default `<appDomainLabel>.app[-<env>].<suffix>` hostnames across all lifecycle environments, plus the custom hostnames bound to the app — each with its binding state and, for custom hostnames, its DNS ownership verification state.', $sdkwork_catalog${"en-US":"Returns every hostname the app publishes on — the default `<appDomainLabel>.app[-<env>].<suffix>` hostnames across all lifecycle environments, plus the custom hostnames bound to the app — each with its binding state and, for custom hostnames, its DNS ownership verification state."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["app"]$sdkwork_catalog$::jsonb, FALSE, 440),
  ('8ddd0ed8-87e7-5272-8a12-7e80897126a1', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'apps.composition.update', 'PUT', '/app/v3/api/apps/{appId}/composition', 'Replace and publish the complete live app composition', $sdkwork_catalog${"en-US":"Replace and publish the complete live app composition"}$sdkwork_catalog$::jsonb, 'Atomically replaces the normalized app composition, appends an immutable AppRevision, and enqueues complete runtime-set assignments. Live Drive or Knowledgebase content changes do not call this operation and do not create releases or deployments.', $sdkwork_catalog${"en-US":"Atomically replaces the normalized app composition, appends an immutable AppRevision, and enqueues complete runtime-set assignments. Live Drive or Knowledgebase content changes do not call this operation and do not create releases or deployments."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["app"]$sdkwork_catalog$::jsonb, FALSE, 450),
