  ('0e6bb48b-c0f9-5bbe-8fd1-d065145ba137', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'apps.sourceSpecs.list', 'GET', '/app/v3/api/apps/{appId}/source_specs', 'List an app''s source specs', $sdkwork_catalog${"en-US":"List an app's source specs"}$sdkwork_catalog$::jsonb, 'The app''s sources, one row per spec. A spec is a *source* dimension, not a delivery variant: a PC bundle and an H5 bundle are two rows here, and the published app keeps a single hostname while the edge picks the spec from the request''s client classification.', $sdkwork_catalog${"en-US":"The app's sources, one row per spec. A spec is a *source* dimension, not a delivery variant: a PC bundle and an H5 bundle are two rows here, and the published app keeps a single hostname while the edge picks the spec from the request's client classification."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["app"]$sdkwork_catalog$::jsonb, FALSE, 510),
  ('9bcd340e-02e1-5921-8d28-f507cb69439e', 100001, '96e86bf2-56be-5330-8f12-242897104727', 'apps.sourceSpecs.create', 'POST', '/app/v3/api/apps/{appId}/source_specs', 'Declare a source spec for an app', $sdkwork_catalog${"en-US":"Declare a source spec for an app"}$sdkwork_catalog$::jsonb, 'Declares a spec without a source. The source is registered afterwards by `apps.sourceSpecs.bindSource`, so the routing shape can be reviewed before anything is uploaded. The spec takes effect when the environment is next composed or published (`apps.composition.update`), which is the moment every other composition change takes effect; declaring it here does not publish on its own.', $sdkwork_catalog${"en-US":"Declares a spec without a source. The source is registered afterwards by `apps.sourceSpecs.bindSource`, so the routing shape can be reviewed before anything is uploaded. The spec takes effect when the environment is next composed or published (`apps.composition.update`), which is the moment every other composition change takes effect; declaring it here does not publish on its own."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["app"]$sdkwork_catalog$::jsonb, FALSE, 520),
